  reldyn: {
    Moon: "A supportive, nurturing presence. People born to play this card are supportive to you. You likely share a strong sense of intimacy and connection with them.",
    Birth: 'A mirror with which to see yourself. People born to play this card are a mirror to you. You may feel like "two peas in a pod." Or this person may reveal annoying, unacknowledged habits that you have.',
    Mercury: "A close confidant. You have a strong mental connection with people born to play this card. You think alike. It's easy to talk to this person, and you have much to talk about.",
    Venus: "A lover and/or a dear companion. You may feel inexplicably drawn to people who have this card to play, like the arrow of Cupid has pierced your heart.",
    Mars: "Sparks fly and/or passion heats up. People born to play this card stimulate you and excite you. However, they may also compete with you, challenge you, and confront you.",
    Jupiter: "An expansive influence in your life. You benefit from people born to play this card. These people expand your horizons, opening you to receive more of life's abundance.",
    Saturn: "A teacher or a taskmaster. People born to play this card may guide you in life. They remind you of your lessons to learn. As such, there could be friction and resistance between you both.",
    Uranus: "A friendly, but variable presence. You may be friends with and receive pivotal benefit from someone with this card to play. But their connection to you may be uneven and unpredictable. And they may be full of surprises.",
    Neptune: "An object of your hopes and fears. This person may be dreamy to you. You may see this person through rose-colored glasses, as if they could do no wrong... until that illusion is shattered, and you must re-establish your connection on solid ground.",
    Pluto: "A shadowy, uneasy presence. People with this card to play reveal your shadow side, the very thing you may try to keep hidden. Until you are completely comfortable facing your own shadow, you may find these people awkward, invasive, and repugnant.",
    "The Princess": "A possible gift in your life. People with this card to play show up for you as a gift, if and when you are ready to welcome them fully into your life.",
    "The Prince": "Someone who tests your resolve. People with this card to play may irk you or frustrate you. Energetically, they challenge you to grow and take personal responsibility for your life.",
    "The Queen": "An advocate of your growth. People with this card to play help you embody the fullness of who you are in life. As such, they may take a supportive role in your life.",
    "The King": "An example for you to follow. People with this card to play will, at their best, model for you the path of your own greatness. You may, however, feel like they are distant, mysterious, or aloof.",
    "Soul Challenge": "A lucky recipient of your generosity. If someone plays your Soul Challenge card, then your card is their Soul Gift card. It means your role is to support them and give to them, and that you may or may not like. Negatively, people with this card to play may seem to exemplify all that you find intolerable about humanity. It means you may have a knee-jerk aversion to them. And/or, you may be jealous or envious of their ability to succeed."
  }
